using Shared.Infrastructure.DTO;

namespace ComplianceService.Domain;

/// <summary>
/// Final response model for Compliance Copilot queries.
/// Contains AI-assisted summary, structured findings, and non-binding suggestions.
/// No approvals or certifications - human review always required.
/// </summary>
public class CopilotResponse
{
    /// <summary>
    /// The type of question that was processed.
    /// </summary>
    public CopilotQuestionType QuestionType { get; set; }

    /// <summary>
    /// AI-assisted summary explanation of the compliance status.
    /// This is generated by LLM to help explain the findings.
    /// </summary>
    public string Summary { get; set; } = string.Empty;

    /// <summary>
    /// Structured list of compliance gaps/findings detected by rule-based analysis.
    /// These are deterministic findings, not AI-generated.
    /// </summary>
    public List<GapResult> Findings { get; set; } = new();

    /// <summary>
    /// Non-binding suggested next steps based on the findings.
    /// These are recommendations only and do not constitute approvals or certifications.
    /// </summary>
    public List<SuggestedNextStep> SuggestedNextSteps { get; set; } = new();

    /// <summary>
    /// Explainability metadata describing how the response was generated.
    /// </summary>
    public ExplainabilityDto Explainability { get; set; } = null!;

    /// <summary>
    /// Source entity references used in the analysis.
    /// </summary>
    public SourceReferences SourceReferences { get; set; } = new();

    /// <summary>
    /// Indicates that human review is required for this response.
    /// Always true - no automated approvals or certifications.
    /// </summary>
    public bool HumanReviewRequired => true;

    /// <summary>
    /// Safety validation result. Contains warning banner if unsafe language is detected.
    /// Content is NOT modified - warnings are displayed alongside original content.
    /// </summary>
    public CopilotSafetyResult? SafetyValidation { get; set; }

    /// <summary>
    /// Warning banner text to display if safety violations are detected.
    /// This is a visible warning - content is NOT silently modified.
    /// </summary>
    public string? SafetyWarningBanner => SafetyValidation?.WarningBanner;
}

/// <summary>
/// A suggested next step (non-binding recommendation).
/// </summary>
public class SuggestedNextStep
{
    /// <summary>
    /// Priority level of the suggestion.
    /// </summary>
    public SuggestionPriority Priority { get; set; }

    /// <summary>
    /// Description of the suggested action.
    /// </summary>
    public string Description { get; set; } = string.Empty;

    /// <summary>
    /// Optional reference to a related gap finding.
    /// </summary>
    public Guid? RelatedGapId { get; set; }

    /// <summary>
    /// Optional reference to a related entity (e.g., ControlId, TaskId).
    /// </summary>
    public Dictionary<string, string> EntityReferences { get; set; } = new();
}

/// <summary>
/// Priority level for suggested next steps.
/// </summary>
public enum SuggestionPriority
{
    /// <summary>
    /// High priority - should be addressed soon.
    /// </summary>
    High,

    /// <summary>
    /// Medium priority - should be addressed.
    /// </summary>
    Medium,

    /// <summary>
    /// Low priority - can be addressed later.
    /// </summary>
    Low
}

/// <summary>
/// Source entity references used in the copilot analysis.
/// </summary>
public class SourceReferences
{
    /// <summary>
    /// Program ID if referenced.
    /// </summary>
    public Guid? ProgramId { get; set; }

    /// <summary>
    /// Program Platform ID if available.
    /// </summary>
    public string? ProgramPlatformId { get; set; }

    /// <summary>
    /// Control ID if referenced.
    /// </summary>
    public Guid? ControlId { get; set; }

    /// <summary>
    /// Control code if available (e.g., "NABH-01").
    /// </summary>
    public string? ControlCode { get; set; }

    /// <summary>
    /// Regulation ID if referenced.
    /// </summary>
    public Guid? RegulationId { get; set; }

    /// <summary>
    /// Task ID if referenced.
    /// </summary>
    public Guid? TaskId { get; set; }

    /// <summary>
    /// Objective element ID if referenced.
    /// </summary>
    public Guid? ObjectiveElementId { get; set; }

    /// <summary>
    /// Audit session ID if referenced.
    /// </summary>
    public Guid? AuditSessionId { get; set; }

    /// <summary>
    /// List of audit finding IDs if referenced.
    /// </summary>
    public List<Guid> AuditFindingIds { get; set; } = new();

    /// <summary>
    /// List of evidence IDs if referenced.
    /// </summary>
    public List<Guid> EvidenceIds { get; set; } = new();
}
